def main():
    out = [
        "<?php",
        "",
        "/**",
        " * Rest catalog rows for missing admin UI keys (parent adds chrome).",
        " */",
        "",
        "$t = static fn (string $zh, string $en, string $de, string $es, string $fr, string $ko, string $pt, string $ja): array => compact('zh', 'en', 'de', 'es', 'fr', 'ko', 'pt', 'ja');",
        "",
        "return [",
    ]
    seen = set()
    for row in ROWS:
        key, zh, en, de, es, fr, ko, pt, ja = row
        if key in seen:
            raise SystemExit(f"duplicate key {key}")
        seen.add(key)
        args = ", ".join(php_s(x) for x in (zh, en, de, es, fr, ko, pt, ja))
        out.append(f"    '{key}' => $t({args}),")
    out.append("];")
    out.append("")
    dest = ROOT / "_catalog_rest.php"
    dest.write_text("\n".join(out), encoding="utf-8")
    print(f"wrote {len(ROWS)} keys -> {dest}")


if __name__ == "__main__":
    main()

